/**
 * An attempt to use the Java 8 streams to look up a more complicated query.
 * <p>
 * FYI, the equivalent SPARQL version (untested):
 *
 * <pre>
 *     SELECT ?orgName WHERE {
 *             ?org foaf:name ?orgName .
 *             ?alice foaf:member ?org .
 *             ?bob foaf:member ?org .
 *             ?alice foaf:knows ?bob .
 *           FILTER NOT EXIST { ?bob foaf:knows ?alice }
 *    }
 * </pre>
 *
 * @throws Exception If test fails
 */
@Test
public void testWhyJavaStreamsMightNotTakeOverFromSparql() throws Exception {
    Assume.assumeNotNull(bnode1, bnode2, secretClubName);
    // Find a secret organizations
    try (Stream<? extends Triple> stream = graph.stream(null, knows, null)) {
        assertEquals("\"The Secret Club\"", // Find One-way "knows"
        stream.filter(t -> !graph.contains((BlankNodeOrIRI) t.getObject(), knows, t.getSubject())).map(knowsTriple -> {
            try (Stream<? extends Triple> memberOf = graph.// and those they know, what are they
            // member of?
            stream((BlankNodeOrIRI) knowsTriple.getObject(), member, null)) {
                return memberOf.// keep those which first-guy is a
                // member of
                filter(memberTriple -> graph.contains(knowsTriple.getSubject(), member, // First hit is good enough
                memberTriple.getObject())).findFirst().get().getObject();
            }
        }).// then look up the name of that org
        map(org -> {
            try (Stream<? extends Triple> orgName = graph.stream((BlankNodeOrIRI) org, name, null)) {
                return orgName.findFirst().get().getObject().ntriplesString();
            }
        }).findFirst().get());
    }
}

